            version_core, pre_release = main_part.split('-', 1)
        else:
            version_core, pre_release = main_part, None

        # Parse major.minor.patch
        major, minor, patch = map(int, version_core.split('.'))

        # Parse pre-release identifiers
        pre_parts = []
        if pre_release:
            for part in pre_release.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)

        return (major, minor, patch), pre_parts

    v1_core, v1_pre = parse_version(a)
    v2_core, v2_pre = parse_version(b)

    # 1. Compare major, minor, patch
    if v1_core < v2_core:
        return -1
    if v1_core > v2_core:
        return 1

    # 2. Pre-release precedence
    # A version with pre-release is LOWER than one without
    if v1_pre and not v2_pre:
        return -1
    if not v1_pre and v2_pre:
        return 1
    if not v1_pre and not v2_pre:
        return 0

    # 3. Compare pre-release identifiers dot by dot
    for p1, p2 in zip(v1_pre, v2_pre):
        if type(p1) != type(p2):
            # Numeric identifiers have lower precedence than non-numeric
            return -1 if isinstance(p1, int) else 1
        if p1 < p2:
            return -1
        if p1 > p2:
            return 1

    # 4. If all parts equal, the one with more identifiers is higher
    if len(v1_pre) < len(v2_pre):
        return -1
    if len(v1_pre) > len(v2_pre):
        return 1

    return 0
